// --- Clutch key helpers (added feature) ---------------------------------------

// KeyboardEvent.code -> Windows virtual-key code, for clutch key capture.
const CLUTCH_KEYBOARD_CODE_TO_VK = {
	"Backspace": 0x08,
	"Tab": 0x09,
	"Enter": 0x0D,
	"NumpadEnter": 0x0D,
	"Pause": 0x13,
	"CapsLock": 0x14,
	"Space": 0x20,
	"PageUp": 0x21,
	"PageDown": 0x22,
	"End": 0x23,
	"Home": 0x24,
	"ArrowLeft": 0x25,
	"ArrowUp": 0x26,
	"ArrowRight": 0x27,
	"ArrowDown": 0x28,
	"PrintScreen": 0x2C,
	"Insert": 0x2D,
	"Delete": 0x2E,
	"MediaTrackNext": 0xB0,
	"MediaTrackPrevious": 0xB1,
	"MediaPlayPause": 0xB3,
	"MediaStop": 0xB4,
	"VolumeMute": 0xAD,
	"VolumeDown": 0xAE,
	"VolumeUp": 0xAF,
	"NumLock": 0x90,
	"ScrollLock": 0x91,
	"ShiftLeft": 0xA0,
	"ShiftRight": 0xA1,
	"ControlLeft": 0xA2,
	"ControlRight": 0xA3,
	"AltLeft": 0xA4,
	"AltRight": 0xA5,
	"MetaLeft": 0x5B,
	"MetaRight": 0x5C,
	"ContextMenu": 0x5D,
	"NumpadMultiply": 0x6A,
	"NumpadAdd": 0x6B,
	"NumpadSubtract": 0x6D,
	"NumpadDecimal": 0x6E,
	"NumpadDivide": 0x6F,
	"Semicolon": 0xBA,
	"Equal": 0xBB,
	"Comma": 0xBC,
	"Minus": 0xBD,
	"Period": 0xBE,
	"Slash": 0xBF,
	"Backquote": 0xC0,
	"BracketLeft": 0xDB,
	"Backslash": 0xDC,
	"BracketRight": 0xDD,
	"Quote": 0xDE,
	"IntlBackslash": 0xE2,
	"IntlRo": 0xCA,
};
for (let i = 0; i <= 9; i++) {
	CLUTCH_KEYBOARD_CODE_TO_VK[`Digit${i}`] = 0x30 + i;
	CLUTCH_KEYBOARD_CODE_TO_VK[`Numpad${i}`] = 0x60 + i;
}
for (const letter of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") {
	CLUTCH_KEYBOARD_CODE_TO_VK[`Key${letter}`] = letter.charCodeAt(0);
}
for (let i = 1; i <= 24; i++) {
	CLUTCH_KEYBOARD_CODE_TO_VK[`F${i}`] = 0x70 + i - 1;
}

// Exported for the camera touch-zone overlay (added feature), which captures
// and displays clutch-style key specs the same way.
export function keyboardEventToClutchKeySpec(event) {
	const vk = CLUTCH_KEYBOARD_CODE_TO_VK[event.code];
	if (vk === undefined) {
		return null;
	}
	return `vk:0x${vk.toString(16)}`;
}

// Shared multi-key sequence capture (added feature, v26). Records keyboard
// keys in press order (max 5) and finishes shortly after everything has been
// released, so both chords (hold Ctrl, tap C) and staggered sequences (tap
// Ctrl, then tap C) are captured as "vk:0x11+vk:0x43". A mouse button finishes
// immediately with a single mouse spec; Esc cancels; losing the window keeps
// what was recorded. Used by the Joy-To-Key target capture and the camera
// touch-zone overlay capture. Returns a dispose() function.
//
// @param {object} options
// @param {(event: KeyboardEvent) => string|null} options.keyboardEventToSpec
//   maps a keyboard event to a key spec (the two callers use different
//   mappings: event.code based for the overlay, event.keyCode based for the
//   settings editor).
// @param {(keySpec: string|null) => void} options.finish called once with the
//   joined sequence spec ("a+b+c"), a single mouse spec, or null on cancel.
// @returns {() => void} dispose - removes all listeners (safe to call twice).
export function createKeySequenceCapture({ keyboardEventToSpec, finish, graceMs = 350, maxKeys = 5 }) {
	const pressed = []; // recorded specs, in press order
	const held = new Set(); // specs currently physically down
	let finishTimer = null;
	let disposed = false;
	const scheduleFinish = () => {
		clearTimeout(finishTimer);
		if (pressed.length > 0 && held.size === 0) {
			finishTimer = setTimeout(() => {
				dispose();
				finish(pressed.join("+"));
			}, graceMs);
		}
	};
	const onKeyDown = (event) => {
		if (disposed) {
			return;
		}
		event.preventDefault();
		event.stopPropagation();
		if (event.repeat) {
			return;
		}
		if (event.key === "Escape" && held.size === 0) {
			dispose();
			finish(null);
			return;
		}
		const spec = keyboardEventToSpec(event);
		if (!spec || held.has(spec)) {
			return;
		}
		held.add(spec);
		if (pressed.length < maxKeys && !pressed.includes(spec)) {
			pressed.push(spec);
		}
	};
	const onKeyUp = (event) => {
		if (disposed) {
			return;
		}
		const spec = keyboardEventToSpec(event);
		if (spec) {
			held.delete(spec);
			scheduleFinish();
		}
	};
	const onMouseDown = (event) => {
		if (disposed) {
			return;
		}
		event.preventDefault();
		event.stopPropagation();
		const specs = ["mouse:left", "mouse:middle", "mouse:right", "mouse:x1", "mouse:x2"];
		dispose();
		finish(specs[event.button] ?? null);
	};
	const onBlur = () => {
		if (disposed) {
			return;
		}
		dispose();
		finish(pressed.length ? pressed.join("+") : null);
	};
	function dispose() {
		disposed = true;
		clearTimeout(finishTimer);
		window.removeEventListener("keydown", onKeyDown, true);
		window.removeEventListener("keyup", onKeyUp, true);
		window.removeEventListener("mousedown", onMouseDown, true);
		window.removeEventListener("blur", onBlur);
	}
	window.addEventListener("keydown", onKeyDown, true);
	window.addEventListener("keyup", onKeyUp, true);
	window.addEventListener("mousedown", onMouseDown, true);
	window.addEventListener("blur", onBlur);
	return dispose;
}

// Standard gamepad mapping (Gamepad API button index -> XInput button name)
const CLUTCH_GAMEPAD_BUTTON_NAMES = ["a", "b", "x", "y", "lb", "rb", "lt", "rt", "back", "start", "l3", "r3", "up", "down", "left", "right"];
const CLUTCH_GAMEPAD_DISPLAY_NAMES = ["A", "B", "X", "Y", "LB", "RB", "LT", "RT", "Back", "Start", "L3", "R3", "↑", "↓", "←", "→"];

// Virtual-key code -> readable name (for keys not obvious from the code)
const CLUTCH_VK_DISPLAY_NAMES = {
	0x08: "Backspace", 0x09: "Tab", 0x0D: "Enter", 0x10: "Shift", 0x11: "Ctrl",
	0x12: "Alt", 0x13: "Pause", 0x14: "CapsLock", 0x1B: "Esc", 0x20: "Space",
	0x21: "Page Up", 0x22: "Page Down", 0x23: "End", 0x24: "Home",
	0x25: "←", 0x26: "↑", 0x27: "→", 0x28: "↓",
	0x2C: "Print Screen", 0x2D: "Insert", 0x2E: "Delete",
	0x30: "0", 0x31: "1", 0x32: "2", 0x33: "3", 0x34: "4", 0x35: "5", 0x36: "6", 0x37: "7", 0x38: "8", 0x39: "9",
	0x41: "A", 0x42: "B", 0x43: "C", 0x44: "D", 0x45: "E", 0x46: "F", 0x47: "G", 0x48: "H", 0x49: "I", 0x4A: "J",
	0x4B: "K", 0x4C: "L", 0x4D: "M", 0x4E: "N", 0x4F: "O", 0x50: "P", 0x51: "Q", 0x52: "R", 0x53: "S", 0x54: "T",
	0x55: "U", 0x56: "V", 0x57: "W", 0x58: "X", 0x59: "Y", 0x5A: "Z",
	0x5B: "Left Win", 0x5C: "Right Win", 0x5D: "Menu",
	0x60: "Num0", 0x61: "Num1", 0x62: "Num2", 0x63: "Num3", 0x64: "Num4",
	0x65: "Num5", 0x66: "Num6", 0x67: "Num7", 0x68: "Num8", 0x69: "Num9",
	0x6A: "Num*", 0x6B: "Num+", 0x6D: "Num-", 0x6E: "Num.", 0x6F: "Num/",
	0x90: "NumLock", 0x91: "ScrollLock",
	0xA0: "LShift", 0xA1: "RShift", 0xA2: "LCtrl", 0xA3: "RCtrl", 0xA4: "LAlt", 0xA5: "RAlt",
	0xBA: ";", 0xBB: "=", 0xBC: ",", 0xBD: "-", 0xBE: ".", 0xBF: "/", 0xC0: "`",
	0xDB: "[", 0xDC: "\\", 0xDD: "]", 0xDE: "'", 0xE2: "Intl\\",
	0xAD: "Mute", 0xAE: "Vol-", 0xAF: "Vol+",
	0xB0: "Next Track", 0xB1: "Prev Track", 0xB3: "Play/Pause", 0xB4: "Stop",
	0xCA: "IntlRo",
};
for (let i = 1; i <= 24; i++) {
	CLUTCH_VK_DISPLAY_NAMES[0x70 + i - 1] = `F${i}`;
}

// Friendly key names accepted inside sequence specs (v26), for display.
const CLUTCH_FRIENDLY_KEY_NAMES = {
	"ctrl": "Ctrl", "control": "Ctrl", "shift": "Shift", "alt": "Alt",
	"win": "Win", "meta": "Win", "super": "Win",
	"space": "Space", "spacebar": "Space", "enter": "Enter", "return": "Enter",
	"esc": "Esc", "escape": "Esc", "tab": "Tab", "backspace": "Backspace",
	"bksp": "Backspace", "delete": "Delete", "del": "Delete", "insert": "Insert",
	"ins": "Insert", "home": "Home", "end": "End", "pageup": "Page Up",
	"pgup": "Page Up", "pagedown": "Page Down", "pgdn": "Page Down",
	"up": "↑", "down": "↓", "left": "←", "right": "→",
	"arrowup": "↑", "arrowdown": "↓", "arrowleft": "←", "arrowright": "→",
	"capslock": "CapsLock", "caps": "CapsLock", "menu": "Menu",
	"contextmenu": "Menu", "printscreen": "Print Screen", "prtsc": "Print Screen",
};

export function clutchKeyDisplayValue(keySpec, t) {
	// Sequence spec (added feature, v26): several keys joined by "+"
	// (e.g. "vk:0x11+vk:0x43" or "ctrl+c"). Format each element and join.
	// (gamepad specs never contain "+", and mouse/vk specs don't either.)
	if (typeof keySpec === "string" && keySpec.includes("+") && !keySpec.startsWith("gamepad:")) {
		const unassigned = t("settings.clutchKey.unassigned", { defaultValue: "Not set" });
		const parts = keySpec
			.split("+")
			.map((part) => clutchKeyDisplayValue(part.trim(), t))
			.filter((label) => label && label !== unassigned);
		if (parts.length > 0) {
			return parts.join(" + ");
		}
	}
	return clutchKeySingleDisplayValue(keySpec, t);
}

function clutchKeySingleDisplayValue(keySpec, t) {
	if (typeof keySpec !== "string" || !keySpec) {
		return t("settings.clutchKey.unassigned", { defaultValue: "Not set" });
	}
	// Friendly key name (sequence specs may contain them, added in v26).
	if (!keySpec.includes(":")) {
		const lower = keySpec.toLowerCase();
		if (CLUTCH_FRIENDLY_KEY_NAMES[lower]) {
			return CLUTCH_FRIENDLY_KEY_NAMES[lower];
		}
		// F1..F24 and single letters/digits ("c", "5").
		if (/^f([1-9]|1\d|2[0-4])$/.test(lower)) {
			return `F${lower.slice(1)}`;
		}
		if (/^[a-z0-9]$/.test(lower)) {
			return lower.toUpperCase();
		}
	}
	if (keySpec.startsWith("mouse:")) {
		const labels = {
			"mouse:left": t("settings.clutchKey.mouseLeft", { defaultValue: "Left mouse button" }),
			"mouse:right": t("settings.clutchKey.mouseRight", { defaultValue: "Right mouse button" }),
			"mouse:middle": t("settings.clutchKey.mouseMiddle", { defaultValue: "Middle mouse button" }),
			"mouse:x1": t("settings.clutchKey.mouseX1", { defaultValue: "Mouse X1 (back)" }),
			"mouse:x2": t("settings.clutchKey.mouseX2", { defaultValue: "Mouse X2 (forward)" }),
			"mouse:wheelup": t("settings.headStickKeymap.optWheelUp", { defaultValue: "Mouse wheel up" }),
			"mouse:wheeldown": t("settings.headStickKeymap.optWheelDown", { defaultValue: "Mouse wheel down" }),
		};
		return labels[keySpec] || keySpec;
	}
	if (keySpec.startsWith("gamepad:")) {
		let rest = keySpec.slice("gamepad:".length);
		// Nintendo HID spec: "hidL:up", "hidR:a", "hidP:zl" - Joy-Con (L/R) or
		// Pro Controller read directly through the Windows HID API.
		const hidMatch = rest.match(/^hid([LRP]):([a-z]+)$/);
		if (hidMatch) {
			const kindLabel = hidMatch[1] === "L"
				? t("settings.clutchKey.joyconL", { defaultValue: "Joy-Con (L)" })
				: hidMatch[1] === "R"
					? t("settings.clutchKey.joyconR", { defaultValue: "Joy-Con (R)" })
					: t("settings.clutchKey.proController", { defaultValue: "Pro Controller" });
			const index = CLUTCH_GAMEPAD_BUTTON_NAMES.indexOf(hidMatch[2]);
			const name = index !== -1 ? CLUTCH_GAMEPAD_DISPLAY_NAMES[index] : hidMatch[2].toUpperCase();
			return kindLabel + " " + name;
		}
		// Optional device pin "@dN" (winmm capture pins the exact joystick
		// device, e.g. Joy-Con L and Joy-Con R are separate devices).
		let device = null;
		const at = rest.lastIndexOf("@");
		if (at !== -1 && /^d\d+$/.test(rest.slice(at + 1))) {
			device = parseInt(rest.slice(at + 2), 10);
			rest = rest.slice(0, at);
		}
		const deviceLabel = device !== null
			? " · " + t("settings.clutchKey.gamepadDevice", { defaultValue: "Device" }) + " " + (device + 1)
			: "";
		// Generic button number (from winmm-class controllers): "btn3" -> "Button 3".
		if (/^btn\d+$/.test(rest)) {
			const number = parseInt(rest.slice(3), 10);
			return t("settings.clutchKey.gamepad", { defaultValue: "Gamepad" }) + " " +
				t("settings.clutchKey.gamepadButtonNumber", { defaultValue: "Button" }) + " " + number +
				deviceLabel;
		}
		const index = CLUTCH_GAMEPAD_BUTTON_NAMES.indexOf(rest);
		const name = index !== -1 ? CLUTCH_GAMEPAD_DISPLAY_NAMES[index] : rest;
		return t("settings.clutchKey.gamepad", { defaultValue: "Gamepad" }) + " " + name + deviceLabel;
	}
	if (keySpec.startsWith("vk:")) {
		const vk = parseInt(keySpec.slice(3), 16);
		if (!Number.isNaN(vk)) {
			return CLUTCH_VK_DISPLAY_NAMES[vk] || `VK 0x${vk.toString(16).toUpperCase().padStart(2, "0")}`;
		}
	}
	return keySpec;
}

