function ensureJoyconDiagramStyles() {
	if (document.getElementById("tracky-mouse-joycon-styles")) {
		return;
	}
	const styleEl = document.createElement("style");
	styleEl.id = "tracky-mouse-joycon-styles";
	styleEl.textContent = JOYCON_DIAGRAM_STYLES;
	document.head.appendChild(styleEl);
}

// Builds the Joy-Con (L/R) schematic. Returns the element plus helpers to
// highlight a button ("hidL" | "hidR" | "hidP" + button name).
function createJoyconDiagram(t) {
	ensureJoyconDiagramStyles();

	const wrap = document.createElement("div");
	wrap.className = "tm-jc-wrap";

	const label = (key, defaultValue) => t(key, { defaultValue });

	const title = (content, x, y) =>
		`<text class="tm-jc-title" x="${x}" y="${y}" text-anchor="middle">${content}</text>`;
	const text = (content, x, y, extraClass = "") =>
		`<text class="tm-jc-text ${extraClass}" x="${x}" y="${y}" text-anchor="middle" dy="0.34em">${content}</text>`;
	// A hit-testable group wrapping one physical button.
	const part = (dev, name, captionText, inner) =>
		`<g class="tm-jc-btn" data-dev="${dev}" data-btn="${name}" data-caption="${captionText}">${inner}</g>`;
	const disc = (cx, cy, r) => `<circle class="tm-jc-shape" cx="${cx}" cy="${cy}" r="${r}"/>`;
	const stick = (dev, name, captionText, cx, cy) =>
		part(dev, name, captionText, `<circle class="tm-jc-shape" cx="${cx}" cy="${cy}" r="46"/>` +
			`<circle class="tm-jc-shape" cx="${cx}" cy="${cy}" r="33"/>`);
	const triangle = (x, y, direction) => {
		const points = {
			up: `${x},${y - 8} ${x + 8},${y + 6} ${x - 8},${y + 6}`,
			down: `${x},${y + 8} ${x + 8},${y - 6} ${x - 8},${y - 6}`,
			left: `${x - 8},${y} ${x + 6},${y - 8} ${x + 6},${y + 8}`,
			right: `${x + 8},${y} ${x - 6},${y - 8} ${x - 6},${y + 8}`,
		}[direction];
		return `<polygon class="tm-jc-solid" points="${points}"/>`;
	};
	const arrowBtn = (dev, name, captionText, x, y, direction) =>
		part(dev, name, captionText, disc(x, y, 15) + triangle(x, y, direction));

	const captionDefault = label("settings.joyconDiagram.caption", "Hover a mapping below to highlight the matching button.");

	wrap.innerHTML = `
		<svg class="tm-jc-svg" viewBox="0 0 570 480" xmlns="http://www.w3.org/2000/svg" role="img"
			aria-label="${label("settings.joyconDiagram.aria", "Joy-Con (L) and Joy-Con (R) button layout")}">
			${title(label("settings.joyconDiagram.title", "Nintendo Switch Joy-Con"), 285, 24)}

			<!-- Joy-Con (L) -->
			<rect class="tm-jc-shape tm-jc-body" x="30" y="60" width="205" height="380" rx="64"/>
			<line class="tm-jc-shape tm-jc-rail" x1="233" y1="92" x2="233" y2="408"/>
			${part("hidL", "zl", "ZL", `<rect class="tm-jc-shape" x="60" y="26" width="60" height="14" rx="7"/>` + text("ZL", 90, 33))}
			${part("hidL", "l", "L", `<rect class="tm-jc-shape" x="60" y="43" width="60" height="15" rx="7.5"/>` + text("L", 90, 50.5))}
			${part("hidL", "minus", "−", `<rect class="tm-jc-shape" x="190" y="100" width="26" height="9" rx="4.5"/>`)}
			${stick("hidL", "lstick", "L Stick", 133, 182)}
			${arrowBtn("hidL", "up", "↑", 133, 264, "up")}
			${arrowBtn("hidL", "left", "←", 95, 302, "left")}
			${arrowBtn("hidL", "right", "→", 171, 302, "right")}
			${arrowBtn("hidL", "down", "↓", 133, 340, "down")}
			${part("hidL", "capture", label("settings.joyconKeyMap.btnCapture", "Capture"), `<rect class="tm-jc-shape" x="86" y="384" width="22" height="22" rx="6"/>` + `<rect class="tm-jc-shape" x="92" y="390" width="10" height="10" rx="2"/>`)}
			${part("hidL", "sl", "SL", `<rect class="tm-jc-shape" x="226" y="126" width="8" height="34" rx="4"/>` + `<text class="tm-jc-text tm-jc-tiny" x="240" y="143" text-anchor="start" dy="0.34em">SL</text>`)}
			${part("hidL", "sr", "SR", `<rect class="tm-jc-shape" x="226" y="336" width="8" height="34" rx="4"/>` + `<text class="tm-jc-text tm-jc-tiny" x="240" y="353" text-anchor="start" dy="0.34em">SR</text>`)}
			${text(label("settings.clutchKey.joyconL", "Joy-Con (L)"), 132, 462, "tm-jc-tiny")}

			<!-- Joy-Con (R) -->
			<rect class="tm-jc-shape tm-jc-body" x="330" y="60" width="205" height="380" rx="64"/>
			<line class="tm-jc-shape tm-jc-rail" x1="332" y1="92" x2="332" y2="408"/>
			${part("hidR", "zr", "ZR", `<rect class="tm-jc-shape" x="450" y="26" width="60" height="14" rx="7"/>` + text("ZR", 480, 33))}
			${part("hidR", "r", "R", `<rect class="tm-jc-shape" x="450" y="43" width="60" height="15" rx="7.5"/>` + text("R", 480, 50.5))}
			${part("hidR", "plus", "+", `<rect class="tm-jc-shape" x="350" y="100" width="26" height="9" rx="4.5"/>` + `<rect class="tm-jc-shape" x="358.5" y="91.5" width="9" height="26" rx="4.5"/>`)}
			${part("hidR", "x", "X", disc(432, 147, 15) + text("X", 432, 147))}
			${part("hidR", "a", "A", disc(467, 182, 15) + text("A", 467, 182))}
			${part("hidR", "b", "B", disc(432, 217, 15) + text("B", 432, 217))}
			${part("hidR", "y", "Y", disc(397, 182, 15) + text("Y", 397, 182))}
			${stick("hidR", "rstick", "R Stick", 432, 302)}
			${part("hidR", "home", label("settings.joyconKeyMap.btnHome", "Home"), `<circle class="tm-jc-shape" cx="432" cy="386" r="17"/>` + `<path class="tm-jc-shape" d="M424 388 l8-7 8 7 v8 h-16 z"/>`)}
			${part("hidR", "sl", "SL", `<rect class="tm-jc-shape" x="331" y="126" width="8" height="34" rx="4"/>` + `<text class="tm-jc-text tm-jc-tiny" x="345" y="143" text-anchor="start" dy="0.34em">SL</text>`)}
			${part("hidR", "sr", "SR", `<rect class="tm-jc-shape" x="331" y="336" width="8" height="34" rx="4"/>` + `<text class="tm-jc-text tm-jc-tiny" x="345" y="353" text-anchor="start" dy="0.34em">SR</text>`)}
			${text(label("settings.clutchKey.joyconR", "Joy-Con (R)"), 432, 462, "tm-jc-tiny")}
		</svg>
		<div class="tm-jc-caption"></div>
		<div class="tm-jc-hint"></div>
	`;

	// Presentation attributes act as a fallback in case inline styles are
	// blocked; the stylesheet above only adds color and transitions.
	for (const node of wrap.querySelectorAll(".tm-jc-shape")) {
		node.setAttribute("fill", "none");
		node.setAttribute("stroke", "currentColor");
		node.setAttribute("stroke-width", "2");
		node.setAttribute("stroke-linecap", "round");
		node.setAttribute("stroke-linejoin", "round");
	}
	for (const node of wrap.querySelectorAll(".tm-jc-solid")) {
		node.setAttribute("fill", "currentColor");
	}
	for (const node of wrap.querySelectorAll(".tm-jc-text, .tm-jc-title")) {
		node.setAttribute("fill", "currentColor");
	}

	const captionEl = wrap.querySelector(".tm-jc-caption");
	const hintEl = wrap.querySelector(".tm-jc-hint");
	captionEl.textContent = captionDefault;
	hintEl.textContent = label("settings.joyconDiagram.hint", "L Stick / R Stick = press the stick down. Pro Controller uses both layouts.");

	let locked = null;

	const clearActive = () => {
		for (const node of wrap.querySelectorAll(".tm-jc-btn.is-active")) {
			node.classList.remove("is-active");
		}
	};
	const nodesFor = (kind, name) => {
		const selector = kind === "hidP"
			? `.tm-jc-btn[data-btn="${name}"]`
			: `.tm-jc-btn[data-dev="${kind}"][data-btn="${name}"]`;
		return Array.from(wrap.querySelectorAll(selector));
	};
	const applyActive = (kind, name) => {
		clearActive();
		const nodes = nodesFor(kind, name);
		for (const node of nodes) {
			node.classList.add("is-active");
		}
		return nodes.length > 0;
	};

	// Hovering the drawing itself shows what each shape is.
	wrap.addEventListener("mouseover", (event) => {
		const target = event.target instanceof Element ? event.target.closest(".tm-jc-btn") : null;
		if (!target) {
			return;
		}
		clearActive();
		target.classList.add("is-active");
		captionEl.textContent = target.dataset.caption || "";
	});
	wrap.addEventListener("mouseout", (event) => {
		const target = event.target instanceof Element ? event.target.closest(".tm-jc-btn") : null;
		if (!target) {
			return;
		}
		if (locked && applyActive(locked.kind, locked.name)) {
			captionEl.textContent = locked.captionText || "";
		} else {
			clearActive();
			captionEl.textContent = captionDefault;
		}
	});

	return {
		element: wrap,
		highlight(kind, name, captionText) {
			if (!kind || !name) {
				return;
			}
			locked = { kind, name, captionText };
			if (applyActive(kind, name)) {
				captionEl.textContent = captionText || captionDefault;
			}
		},
		clear() {
			locked = null;
			clearActive();
			captionEl.textContent = captionDefault;
		},
	};
}

// TODO: clean up signature which is currently "whatever dependencies were needed to extract this code to a new file"
export function initSettingsUI({
	settingsCategories,
	uiContainer,
	t,
	s,
	getSetOptionsFunction,
}) {
	const elsByGroup = new Map();
	const functionsToUpdateDisabledStates = [];

	// Joy-Con diagram (added feature): built with the Joy-Con group and shared
	// with the key mapping rows, which highlight the button they point at.
	let joyconDiagramController = null;
	const ensureJoyconDiagram = () => {
		if (!joyconDiagramController) {
			joyconDiagramController = createJoyconDiagram(t);
		}
		return joyconDiagramController;
	};

	const disposeController = new AbortController();
	const disposeSignal = disposeController.signal;

	// --- Mode tabs (added feature, v30) -------------------------------------
	// The settings are split into two scenes: "Mouse mode" (everything about
	// the cursor: movement, clicking, head-touch keys) and "Game mode"
	// (virtual gamepad, stick → key mappings, Joy-Con). All groups stay in the
	// DOM; the active tab only decides which ones are displayed, so switching
	// never re-renders and never loses a value that is being edited.
	const MODE_STORAGE_KEY = "tracky-mouse-settings-mode";
	const modeState = { mouse: true, game: true, mouseKey: "vk:0x78", gameKey: "vk:0x79" };
	let settingsMode = "mouse";
	try {
		const stored = localStorage.getItem(MODE_STORAGE_KEY);
		if (stored === "mouse" || stored === "game") {
			settingsMode = stored;
		}
	} catch {
		// localStorage can be unavailable; the tab then simply isn't remembered.
	}

	// --- Setting row layout (added feature, v33) ---------------------------
	// A small layout pass so the settings list reads as blocks instead of a
	// flat list of rows:
	//  • checkboxes move into the control column, so their tick boxes line up
	//    with the dropdowns and key buttons below/above them;
	//  • rows tagged `indent` are drawn as children of the switch above them
	//    (slightly indented, with a soft vertical rail);
	//  • rows tagged `rowGap` start a new block, separated by a dashed rule;
	//  • rows tagged `emphasis` render their label bold, like a heading.
	// The info/reset buttons are prepended to every row, so the checkbox is
	// moved with `order` rather than by reversing the row - that keeps those
	// buttons in place and keeps the columns aligned.
	const ensureRowLayoutStyles = () => {
		if (document.getElementById("tracky-mouse-row-layout-styles")) {
			return;
		}
		const styleEl = document.createElement("style");
		styleEl.id = "tracky-mouse-row-layout-styles";
		styleEl.textContent = `
.tracky-mouse-ui .tracky-mouse-control-row:has(> input[type="checkbox"]) > label {
	flex: 0 0 var(--tm-row-label-width, 160px);
	order: 1;
}
.tracky-mouse-ui .tracky-mouse-control-row:has(> input[type="checkbox"]) > input {
	order: 2;
	/* Chromium gives checkboxes a 4px inline margin; drop it so the tick boxes
	   line up exactly with the dropdowns and key buttons in the same column. */
	margin-inline-start: 0;
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-child {
	--tm-row-label-width: 142px;
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-child > label {
	flex: 0 0 var(--tm-row-label-width, 160px);
	margin-inline-start: 18px;
	position: relative;
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-child .tracky-mouse-label-text {
	min-width: 132px;
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-child > label::before {
	content: "";
	position: absolute;
	inset-inline-start: -12px;
	top: -7px;
	bottom: -7px;
	width: 2px;
	border-radius: 2px;
	background: rgba(128, 128, 128, 0.28);
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-gap {
	margin-top: 10px;
	padding-top: 9px;
	border-top: 1px dashed rgba(128, 128, 128, 0.4);
}
.tracky-mouse-ui .tracky-mouse-control-row.tracky-mouse-row-emphasis .tracky-mouse-label-text {
	font-weight: 600;
}
`;
		document.head.appendChild(styleEl);
	};

	const ensureModeStyles = () => {
		if (document.getElementById("tracky-mouse-mode-styles")) {
			return;
		}
		const styleEl = document.createElement("style");
		styleEl.id = "tracky-mouse-mode-styles";
		styleEl.textContent = `
[data-tracky-mode="mouse"] .tracky-mouse-settings-group[data-mode="game"] { display: none !important; }
[data-tracky-mode="game"] .tracky-mouse-settings-group[data-mode="mouse"] { display: none !important; }
.tracky-mouse-mode-tabs {
	display: flex;
	align-items: center;
	gap: 6px;
	flex-wrap: wrap;
	margin: 0 0 10px;
	padding: 6px 6px 8px;
	border-bottom: 1px solid rgba(128, 128, 128, 0.35);
}
.tracky-mouse-mode-tab {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	padding: 5px 12px;
	border: 1px solid rgba(128, 128, 128, 0.5);
	border-radius: 999px;
	background: transparent;
	color: inherit;
	font: inherit;
	cursor: pointer;
	opacity: 0.75;
}
.tracky-mouse-mode-tab[aria-selected="true"] {
	opacity: 1;
	font-weight: 600;
	border-color: currentColor;
	background: rgba(128, 128, 128, 0.16);
}
.tracky-mouse-mode-dot {
	width: 8px;
	height: 8px;
	border-radius: 50%;
	background: rgba(128, 128, 128, 0.55);
	box-shadow: none;
}
.tracky-mouse-mode-dot.tracky-mouse-mode-on {
	background: #22a06b;
	box-shadow: 0 0 4px rgba(34, 160, 107, 0.8);
}
.tracky-mouse-mode-power {
	margin-left: auto;
	padding: 4px 10px;
	border: 1px solid rgba(128, 128, 128, 0.5);
	border-radius: 6px;
	background: transparent;
	color: inherit;
	font: inherit;
	font-size: 90%;
	cursor: pointer;
}
.tracky-mouse-mode-power[data-active="false"] { opacity: 0.7; }
`;
		document.head.appendChild(styleEl);
	};

	const modeTabs = [];

	const renderModeTabs = () => {
		const mouseOff = !modeState.mouse;
		const gameOff = !modeState.game;
		for (const { element, mode, dot } of modeTabs) {
			element.setAttribute("aria-selected", settingsMode === mode ? "true" : "false");
			const on = mode === "mouse" ? !mouseOff : !gameOff;
			dot.classList.toggle("tracky-mouse-mode-on", on);
			element.title = on
				? t("settings.mode.on", { defaultValue: "On" })
				: t("settings.mode.off", { defaultValue: "Off" });
		}
		const powerBtn = modeTabs.powerButton;
		if (powerBtn) {
			const mode = settingsMode;
			const on = mode === "mouse" ? !mouseOff : !gameOff;
			const keySpec = mode === "mouse" ? modeState.mouseKey : modeState.gameKey;
			const keyLabel = keySpec ? clutchKeyDisplayValue(keySpec, t) : "";
			const name = mode === "mouse"
				? t("settings.mode.mouse.label", { defaultValue: "Mouse mode" })
				: t("settings.mode.game.label", { defaultValue: "Game mode" });
			const action = on
				? t("settings.mode.turnOff", { defaultValue: "Turn off" })
				: t("settings.mode.turnOn", { defaultValue: "Turn on" });
			const parts = `${name} · ${action}`;
			powerBtn.textContent = keyLabel ? `${parts} (${keyLabel})` : parts;
			powerBtn.dataset.active = on ? "true" : "false";
		}
	};
	modeTabs.powerButton = null;

	const applyMode = (mode) => {
		settingsMode = mode === "game" ? "game" : "mouse";
		if (document.body) {
			document.body.dataset.trackyMode = settingsMode;
		}
		uiContainer.dataset.trackyMode = settingsMode;
		try {
			localStorage.setItem(MODE_STORAGE_KEY, settingsMode);
		} catch {
			// ignore
		}
		renderModeTabs();
	};

	const buildModeTabs = (parentEl) => {
		ensureModeStyles();
		const bar = document.createElement("div");
		bar.className = "tracky-mouse-mode-tabs";
		bar.setAttribute("role", "tablist");
		for (const [mode, defaultLabel] of [["mouse", "Mouse mode"], ["game", "Game mode"]]) {
			const btn = document.createElement("button");
			btn.type = "button";
			btn.className = "tracky-mouse-mode-tab";
			btn.dataset.mode = mode;
			btn.setAttribute("role", "tab");
			const dot = document.createElement("span");
			dot.className = "tracky-mouse-mode-dot";
			const labelEl = document.createElement("span");
			labelEl.textContent = t(`settings.mode.${mode}.label`, { defaultValue: defaultLabel });
			btn.append(dot, labelEl);
			btn.addEventListener("click", () => applyMode(mode));
			bar.appendChild(btn);
			modeTabs.push({ element: btn, mode, dot });
		}
		const powerBtn = document.createElement("button");
		powerBtn.type = "button";
		powerBtn.className = "tracky-mouse-mode-power";
		powerBtn.addEventListener("click", () => {
			window.electronAPI?.toggleMode?.(settingsMode);
		});
		bar.appendChild(powerBtn);
		modeTabs.powerButton = powerBtn;
		parentEl.prepend(bar);
		applyMode(settingsMode);
	};

	if (window.electronAPI?.onModeState) {
		window.electronAPI.onModeState((state) => {
			if (!state) {
				return;
			}
			if (typeof state.mouse === "boolean") {
				modeState.mouse = state.mouse;
			}
			if (typeof state.game === "boolean") {
				modeState.game = state.game;
			}
			if (typeof state.mouseKey === "string") {
				modeState.mouseKey = state.mouseKey;
			}
			if (typeof state.gameKey === "string") {
				modeState.gameKey = state.gameKey;
			}
			renderModeTabs();
		});
	}
	if (window.electronAPI?.getModeState) {
		window.electronAPI.getModeState().then((state) => {
			if (!state) {
				return;
			}
			Object.assign(modeState, state);
			renderModeTabs();
		}).catch(() => {});
	}

	function buildSettingsUI(parentEl, settingsCategories) {
		ensureRowLayoutStyles();
		buildModeTabs(parentEl);


		for (const category of settingsCategories) {
			const detailsEl = buildSettingGroupUI(category);
			const bodyEl = detailsEl.querySelector(".tracky-mouse-details-body");
			traverseSettings(category.settings, (setting, parentGroup) => {
				const parentGroupElement = (elsByGroup.get(parentGroup) ?? bodyEl);

				let el;
				if (setting.type === "group") {
					el = buildSettingGroupUI(setting);
				} else {
					el = buildSettingItemUI(setting);
				}
				parentGroupElement.appendChild(el);

				if (setting.disabled) {
					const updateDisabledState = () => {
						// TODO: supply a message for why it's disabled (can update `disabled()` to return a string or object)
						const disabled = setting.disabled?.() ?? setting.disabled === true;
						el.classList.toggle("tracky-mouse-disabled", disabled);
						const controls = el.querySelectorAll(`input, select, button`);
						for (const control of controls) {
							if (control.matches(".tracky-mouse-setting-extra-button")) {
								continue;
							}
							// This should handle nested disabled conditions properly
							control.disabled = control.closest(".tracky-mouse-disabled") !== null;
						}
					};
					functionsToUpdateDisabledStates.push(updateDisabledState);
					// Not useful to call updateDisabledState() here because dependent setting values aren't loaded yet
				}
			});

			parentEl.appendChild(detailsEl);

		}

	}

	function buildSettingGroupUI(group) {
		const detailsEl = document.createElement("details");
		// v30: tagged with the mode it belongs to ("mouse" / "game" / "both") so
		// the tab bar can show only the settings of the active scene. Details
		// without a mode (sub-groups) simply follow their parent.
		detailsEl.className = "tracky-mouse-settings-group";
		if (group.mode) {
			detailsEl.dataset.mode = group.mode;
		}
		// TODO: recursive check for visibility - or just define visible() on groups
		if (group.settings.every(setting => setting.visible?.() === false)) {
			detailsEl.hidden = true;
		}
		const summaryEl = document.createElement("summary");
		summaryEl.textContent = group.label;
		detailsEl.appendChild(summaryEl);
		const bodyEl = document.createElement("div");
		bodyEl.className = "tracky-mouse-details-body";
		// Joy-Con diagram (added feature): shown at the top of the group so the
		// button being configured can be matched to the physical controller.
		if (group.diagram === "joycon-lr") {
			bodyEl.appendChild(ensureJoyconDiagram().element);
		}
		detailsEl.appendChild(bodyEl);
		elsByGroup.set(group, bodyEl);
		return detailsEl;
	}

	function buildSettingItemUI(setting) {

		// Validation
		for (const requiredProp of ["label", "className", "key", "type", "default"]) {
			if (setting[requiredProp] === undefined) {
				if (setting.type === "button" && requiredProp === "default") {
					continue; // buttons don't need a default value
				}
				console.warn(`Setting is missing ${requiredProp}:`, setting);
				return;
			}
		}
		for (const importantProp of ["description"]) {
			if (setting[importantProp] === undefined) {
				console.warn(`Setting is missing ${importantProp}:`, setting);
			}
		}
		const rowEl = document.createElement("div");
		rowEl.className = "tracky-mouse-control-row";
		// v33 layout tags (see ensureRowLayoutStyles)
		if (setting.rowGap) {
			rowEl.classList.add("tracky-mouse-row-gap");
		}
		if (setting.indent) {
			rowEl.classList.add("tracky-mouse-row-child");
		}
		if (setting.emphasis) {
			rowEl.classList.add("tracky-mouse-row-emphasis");
		}
		if (setting.type === "slider") {
			rowEl.innerHTML = `
				<label for="${setting.className}"><span class="tracky-mouse-label-text">${setting.label}</span></label>
				<span class="tracky-mouse-labeled-slider">
					<input type="range" id="${setting.className}" min="${setting.min}" max="${setting.max}" class="${setting.className}">
					<span class="tracky-mouse-slider-labels">
						<span class="tracky-mouse-min-label">${setting.labels.min}</span>
						<span class="tracky-mouse-max-label">${setting.labels.max}</span>
					</span>
				</span>
			`;
		} else if (setting.type === "checkbox") {
			// special interest: jspaint wants label not to use parent-child relationship so that os-gui's 98.css checkbox styles can work
			rowEl.innerHTML = `
				<input type="checkbox" id="${setting.className}" class="${setting.className}">
				<label for="${setting.className}"><span class="tracky-mouse-label-text">${setting.label}</span></label>
			`;
		} else if (setting.type === "dropdown") {
			const optionsHtml = setting.options.map(option => `
				<option value="${option.value}">${option.label}</option>
			`.trim()).join("\n");
			rowEl.innerHTML = `
				<label for="${setting.className}"><span class="tracky-mouse-label-text">${setting.label}</span></label>
				<select id="${setting.className}" class="${setting.className}">
					${optionsHtml}
				</select>
			`;
			if (setting.options.some(option => option.description)) {
				setting.description += "\n\n" + t("settings.dropdownDescriptionOptionsListHeading", { defaultValue: "Options:" }) + "\n" + setting.options.map(option => `• ${option.label}${option.description ? `: ${option.description}` : ''}`).join("\n");
			}
		} else if (setting.type === "clutchKey") {
			// Clutch mode (added feature): a button that captures the next pressed
			// key (mouse button, keyboard key, or gamepad button) as the clutch key.
			rowEl.innerHTML = `
				<label for="${setting.className}"><span class="tracky-mouse-label-text">${setting.label}</span></label>
				<button type="button" id="${setting.className}" class="${setting.className} tracky-mouse-setting-button tracky-mouse-clutch-key-button"></button>
			`;
		} else if (setting.type === "keySequence") {
			// Gesture click key binding (added feature, v28): a button that
			// records a key SEQUENCE (like the Joy-To-Key "Set key…" targets),
			// e.g. blink click → Ctrl+C, or mouth click → Space.
			rowEl.innerHTML = `
				<label for="${setting.className}"><span class="tracky-mouse-label-text">${setting.label}</span></label>
				<button type="button" id="${setting.className}" class="${setting.className} tracky-mouse-setting-button tracky-mouse-keymap-target"></button>
			`;
		} else if (setting.type === "keymap") {
			// Joy-Con key mappings editor (added feature): rows of
			// [controller][button][target key][delete] + an "add" button.
			rowEl.innerHTML = `
				<label><span class="tracky-mouse-label-text">${setting.label}</span></label>
				<div id="${setting.className}" class="${setting.className} tracky-mouse-keymap-editor"></div>
			`;
		} else if (setting.type === "button") {
			rowEl.innerHTML = `
				<button class="${setting.className} tracky-mouse-setting-button">${setting.label}</button>
			`;
		}
		if (setting.visible?.() === false) {
			rowEl.hidden = true;
		}

		if (setting.description) {
			const toGiveHoverText = rowEl.querySelector(".tracky-mouse-label-text, .tracky-mouse-setting-button");
			if (toGiveHoverText) {
				toGiveHoverText.title = setting.description;
			}
		}

		const infoPopover = document.createElement("div");
		infoPopover.className = "tracky-mouse-setting-info-popover";
		// Avoiding using native popover functionality because
		// the cursor+HUD should go on top in the web demo/web version.
		// TODO: research aria-describedby, aria-haspopup
		// What's the proper way to do a tooltip with explicit toggling?
		// infoPopover.popover = "auto";
		infoPopover.role = "dialog"; // NOT "tooltip"
		infoPopover.hidden = true;
		infoPopover.id = `tracky-mouse-${setting.className}-info-popover`;
		infoPopover.textContent = setting.description;
		infoPopover.title = ""; // avoid redundant tooltip
		rowEl.appendChild(infoPopover);

		const infoButton = document.createElement("button");
		infoButton.className = "tracky-mouse-setting-info-button tracky-mouse-setting-extra-button";
		infoButton.setAttribute("aria-controls", infoPopover.id);
		infoButton.setAttribute("aria-expanded", false);
		infoButton.innerHTML = infoIconSVG;
		// TODO: not sure what the tooltip should say, "Setting info" is just AI-suggested
		// Should it have a tooltip at all? Should it show the whole popover text in the tooltip?
		// Should it show the whole popover itself temporarily?
		infoButton.title = t("settings.settingInfo", { defaultValue: "Setting info" });
		infoButton.setAttribute("aria-label", t("settings.settingInfo", { defaultValue: "Setting info" }));
		if (setting.description) {
			// infoButton.popoverTargetElement = infoPopover;
			infoButton.addEventListener("click", () => {
				infoPopover.hidden = !infoPopover.hidden;
				infoButton.setAttribute("aria-expanded", !infoPopover.hidden);

				// Fallback for positioning the popover when position-area is not supported
				// (position-area isn't supported in Electron 31)
				// This is one-off, whereas position-area is dynamic over time.
				if (!infoPopover.hidden && !("positionArea" in infoPopover.style)) {
					const buttonRect = infoButton.getBoundingClientRect();
					infoPopover.style.top = buttonRect.bottom + "px";
					infoPopover.style.left = buttonRect.left + "px";
					infoPopover.style.position = "absolute";
					const popoverRect = infoPopover.getBoundingClientRect();
					if (popoverRect.bottom > window.innerHeight) {
						infoPopover.style.top = buttonRect.top - popoverRect.height + "px";
					}
				}
			});
			// TODO: use event listener delegation to avoid many event listeners
			addEventListener("pointerdown", (e) => {
				if (!infoPopover.contains(e.target) && !infoButton.contains(e.target)) {
					infoPopover.hidden = true;
					infoButton.setAttribute("aria-expanded", false);
				}
			}, { signal: disposeSignal });
			addEventListener("keydown", (e) => {
				if (e.key === "Escape") {
					infoPopover.hidden = true;
					infoButton.setAttribute("aria-expanded", false);
				}
			}, { signal: disposeSignal });
		} else {
			// Disabled "extra" buttons are hidden by CSS
			// The info button is still included in the DOM to reserve space
			// and align controls without info buttons with those that have them
			// (The only setting type without a default value is "button", for now at least.)
			infoButton.disabled = true;
		}
		rowEl.prepend(infoButton);

		const resetButton = document.createElement("button");
		resetButton.className = "tracky-mouse-setting-reset-button tracky-mouse-setting-extra-button";
		resetButton.innerHTML = resetIconSVG;
		resetButton.title = t("settings.resetSetting", { defaultValue: "Reset to default" });
		resetButton.setAttribute("aria-label", t("settings.resetSetting", { defaultValue: "Reset to default" }));
		if ("default" in setting) {
			resetButton.addEventListener("click", () => {
				setControlValue(setting.default);
				loadValueFromControl();
				save();
				setting.handleSettingChange?.();
				for (const func of functionsToUpdateDisabledStates) {
					func();
				}
			});
		} else {
			// Disabled "extra" buttons are hidden by CSS
			// The reset button is still included in the DOM to reserve space
			// and align controls without reset buttons with those that have them
			// (The only setting type without a default value is "button", for now at least.)
			resetButton.disabled = true;
		}
		rowEl.prepend(resetButton);

		const control = rowEl.querySelector(`.${setting.className}`);
		let controlValue = null; // used only by the "clutchKey" and "keySequence" setting types
		const getControlValue = () => {
			if (setting.type === "slider") {
				return Number(control.value);
			} else if (setting.type === "checkbox") {
				return control.checked;
			} else if (setting.type === "dropdown") {
				return control.value;
			} else if (setting.type === "clutchKey") {
				return controlValue;
			} else if (setting.type === "keySequence") {
				return controlValue;
			} else if (setting.type === "keymap") {
				return controlValue;
			}
		};
		const setControlValue = (value) => {
			if (setting.type === "slider") {
				control.value = value;
			} else if (setting.type === "checkbox") {
				control.checked = value;
			} else if (setting.type === "dropdown") {
				control.value = value;
			} else if (setting.type === "clutchKey") {
				controlValue = value;
				control.textContent = clutchKeyDisplayValue(value, t);
			} else if (setting.type === "keySequence") {
				controlValue = value || "";
				control.textContent = controlValue
					? clutchKeyDisplayValue(controlValue, t)
					: t("settings.joyconKeyMap.setTarget", { defaultValue: "Set key…" });
			} else if (setting.type === "keymap") {
				controlValue = Array.isArray(value) ? value : [];
				renderKeymapEditor?.(); // var-hoisted; no-op until the editor block runs below
			}
		};

		const load = (settings, initialLoad) => {
			// Note: Don't use `... in settings.globalSettings` to check if a setting is defined.
			// We must ignore `undefined` values so that the defaults carry over from the renderer to the main process in the Electron app.
			if (settings.globalSettings?.[setting.key] !== undefined) {
				s[setting.key] = settings.globalSettings[setting.key];
				setControlValue((setting.settingValueToInputValue ?? ((x) => x))(s[setting.key]));
			}
			if (initialLoad) {
				setting.afterInitialLoad?.();
			}
		};
		const loadValueFromControl = () => {
			s[setting.key] = (setting.inputValueToSettingValue ?? ((x) => x))(getControlValue());
		};
		const save = () => {
			const setOptions = getSetOptionsFunction();
			setOptions({ globalSettings: { [setting.key]: s[setting.key] } });
		};

		// Load defaults
		// currently defined in input value units
		setControlValue(setting.default);
		s[setting.key] = (setting.inputValueToSettingValue ?? ((x) => x))(getControlValue());
		// Not useful to call functionsToUpdateDisabledStates here because dependent setting values aren't necessarily loaded yet

		// Handle changes
		control.addEventListener("change", () => {
			loadValueFromControl();
			save();
			// TODO: also call this if the setting is changed through CLI
			// Would be good to have a pattern where it's subscribing to changes to a settings store
			setting.handleSettingChange?.();

			for (const func of functionsToUpdateDisabledStates) {
				func();
			}
		});
		// Handle loading from stored settings
		setting._load = load;

		if (setting.type === "button") {
			control.addEventListener("click", () => {
				setting.onClick?.();
			});
		}

		// Clutch key capture (added feature): clicking the button starts capturing;
		// the next mouse button, keyboard key, or gamepad button becomes the clutch key.
		if (setting.type === "clutchKey") {
			let capturing = false;
			let stopCapturing = null;

			const finishCapture = (keySpec) => {
				stopCapturing?.();
				stopCapturing = null;
				capturing = false;
				control.classList.remove("tracky-mouse-capturing-key");
				if (keySpec) {
					controlValue = keySpec;
					control.textContent = clutchKeyDisplayValue(keySpec, t);
					// Triggers loadValueFromControl + save + handleSettingChange
					control.dispatchEvent(new Event("change"));
				} else {
					// Cancelled: restore the previous label.
					control.textContent = clutchKeyDisplayValue(controlValue, t);
				}
			};

			const startCapture = () => {
				if (capturing) {
					return;
				}
				capturing = true;
				control.classList.add("tracky-mouse-capturing-key");
				control.textContent = t("settings.clutchKey.pressAnyKey", { defaultValue: "Press any key… (Esc to cancel)" });

				const onKeyDown = (event) => {
					event.preventDefault();
					event.stopPropagation();
					if (event.repeat) {
						return;
					}
					if (event.key === "Escape") {
						// Escape cancels capture (it can't be assigned as the clutch key).
						finishCapture(null);
						return;
					}
					const keySpec = keyboardEventToClutchKeySpec(event);
					if (keySpec) {
						finishCapture(keySpec);
					}
					// Keys without a virtual-key mapping are ignored.
				};
				const onMouseDown = (event) => {
					event.preventDefault();
					event.stopPropagation();
					const specs = ["mouse:left", "mouse:middle", "mouse:right", "mouse:x1", "mouse:x2"];
					finishCapture(specs[event.button] ?? null);
				};
				const onBlur = () => {
					finishCapture(null);
				};
				// Capture phase, to get events before the rest of the UI.
				window.addEventListener("keydown", onKeyDown, true);
				window.addEventListener("mousedown", onMouseDown, true);
				window.addEventListener("blur", onBlur);
				let gamepadRaf = 0;
				const pollGamepads = () => {
					const gamepads = navigator.getGamepads?.() ?? [];
					for (const gamepad of gamepads) {
						if (!gamepad) {
							continue;
						}
						for (let index = 0; index < Math.min(gamepad.buttons.length, CLUTCH_GAMEPAD_BUTTON_NAMES.length); index++) {
							if (gamepad.buttons[index]?.pressed) {
								const button = CLUTCH_GAMEPAD_BUTTON_NAMES[index];
								finishCapture(button ? `gamepad:${button}` : null);
								return;
							}
						}
					}
					gamepadRaf = requestAnimationFrame(pollGamepads);
				};
				gamepadRaf = requestAnimationFrame(pollGamepads);
				// Also capture via the helper executable (XInput + winmm), which sees
				// DirectInput-class controllers that the Gamepad API doesn't expose.
				// The helper gets a head start (its specs are guaranteed to match what
				// the watcher reads); the Gamepad API below is the fallback for when
				// the helper isn't available. Whichever detects the press first wins;
				// both are cancelled when the capture ends.
				window.electronAPI?.captureClutchGamepad?.().then((keySpec) => {
					if (capturing && keySpec) {
						finishCapture(keySpec);
					}
				}).catch(() => {});
				stopCapturing = () => {
					window.removeEventListener("keydown", onKeyDown, true);
					window.removeEventListener("mousedown", onMouseDown, true);
					window.removeEventListener("blur", onBlur);
					cancelAnimationFrame(gamepadRaf);
					window.electronAPI?.cancelClutchGamepadCapture?.();
				};
				// Delay the Gamepad API fallback so the helper capture wins when both
				// can see the controller (their button naming can differ).
				setTimeout(() => {
					if (capturing) {
						gamepadRaf = requestAnimationFrame(pollGamepads);
					}
				}, 800);
			};

			control.addEventListener("click", () => {
				if (capturing) {
					return;
				}
				// Exclude the click that activated the button from the capture.
				setTimeout(startCapture, 0);
			});
			disposeSignal.addEventListener("abort", () => {
				stopCapturing?.();
			});
		}

		// Gesture click key sequence capture (added feature, v28): records keys
		// pressed in order - multiple keys allowed, exactly like the Joy-To-Key
		// "Set key…" targets (e.g. hold Ctrl, tap C, release → "Ctrl + C").
		// Right-click (or the small "…" pattern used elsewhere) opens a manual
		// entry prompt for sequences like "ctrl+c", "vk:0x57", "mouse:right".
		if (setting.type === "keySequence") {
			const keySequenceEmptyLabel = () => t("settings.joyconKeyMap.setTarget", { defaultValue: "Set key…" });
			const finishCapture = (keySpec) => {
				if (keySpec) {
					controlValue = keySpec;
					control.textContent = clutchKeyDisplayValue(keySpec, t);
					// Triggers loadValueFromControl + save + handleSettingChange
					control.dispatchEvent(new Event("change"));
				} else {
					// Cancelled: restore the previous label.
					control.textContent = controlValue
						? clutchKeyDisplayValue(controlValue, t)
						: keySequenceEmptyLabel();
				}
			};
			control.addEventListener("click", () => {
				control.textContent = t("settings.clutchKey.pressSequence", { defaultValue: "Press keys in order… (release all to finish · Esc to cancel)" });
				createKeySequenceCapture({
					keyboardEventToSpec: (event) => event.keyCode
						? "vk:0x" + event.keyCode.toString(16).toUpperCase()
						: null,
					finish: finishCapture,
				});
			});
			control.addEventListener("contextmenu", (event) => {
				// Manual sequence entry: type specs by hand, like the Joy-To-Key rows.
				event.preventDefault();
				event.stopPropagation();
				const input = window.prompt(
					t("settings.joyconKeyMap.editTargetPrompt", { defaultValue: "Key sequence - separate keys with + (e.g. ctrl+c, vk:0x11+vk:0x43, mouse:left):" }),
					controlValue || "",
				);
				if (input === null) {
					return;
				}
				const value = input.trim();
				if (value) {
					finishCapture(value);
				} else {
					finishCapture(null);
				}
			});
			control.title = setting.description || "";
		}

		// Joy-Con key mappings editor (added feature). The setting value is an
		// array of { btn: "hidK:name", key: "vk:0x.." | "mouse:.." }.
		if (setting.type === "keymap") {
			// The mapping table needs the full width of the settings pane.
			control.closest(".tracky-mouse-control-row")?.classList.add("tm-jc-wide-row");

			// Press-a-pad-button capture (added feature): instead of picking the
			// controller + button from dropdowns, the user can physically press
			// the button on the Joy-Con / Pro Controller. Uses the helper
			// executable (XInput + winmm + raw Nintendo HID), same as the
			// clutch key capture.
			let padCaptureStop = null; // truthy while a capture is in progress
			const keymapToast = (message) => {
				const toast = document.createElement("div");
				toast.className = "tracky-mouse-toast";
				toast.style.whiteSpace = "pre-wrap";
				toast.textContent = message;
				document.body.appendChild(toast);
				setTimeout(() => {
					toast.remove();
				}, 8000);
			};
			/** Runs one gamepad-button capture; resolves through onCaptured(btn) with e.g. "hidR:a". */
			const capturePadButton = (buttonEl, onCaptured) => {
				if (padCaptureStop) {
					return; // one capture at a time
				}
				const api = window.electronAPI;
				if (!api?.captureClutchGamepad) {
					keymapToast(t("settings.joyconKeyMap.padCaptureFailed", { defaultValue: "Capture is unavailable (the button watcher helper wasn't found)." }));
					return;
				}
				const originalText = buttonEl.textContent;
				const onKeyDown = (event) => {
					if (event.key === "Escape") {
						event.preventDefault();
						event.stopPropagation();
						api.cancelClutchGamepadCapture?.();
						finishCapture(null);
					}
				};
				const finishCapture = (spec) => {
					if (!padCaptureStop) {
						return;
					}
					padCaptureStop = null;
					window.removeEventListener("keydown", onKeyDown, true);
					buttonEl.textContent = originalText;
					if (!spec) {
						return; // cancelled (Esc / second click), or nothing captured
					}
					if (!spec.startsWith("gamepad:hid")) {
						// Joy-To-Key reads Joy-Con / Pro Controller buttons via raw
						// HID; XInput/DInput pads are a different channel.
						keymapToast(t("settings.joyconKeyMap.padCaptureNonNintendo", { defaultValue: "That was a non-Nintendo controller button. Button → keyboard mapping only works with Joy-Con / Pro Controller hardware buttons." }));
						return;
					}
					onCaptured(spec.slice("gamepad:".length));
				};
				buttonEl.textContent = t("settings.joyconKeyMap.padCaptureActive", { defaultValue: "Press a button on the controller… (Esc to cancel)" });
				window.addEventListener("keydown", onKeyDown, true);
				api.captureClutchGamepad().then((spec) => finishCapture(spec));
				padCaptureStop = () => {
					window.removeEventListener("keydown", onKeyDown, true);
					buttonEl.textContent = originalText;
				};
			};
			var renderKeymapEditor = () => { // var: hoisted for setControlValue above
				const mappings = Array.isArray(controlValue) ? controlValue : [];
				const controllerOptions = [
					["hidL", t("settings.clutchKey.joyconL", { defaultValue: "Joy-Con (L)" })],
					["hidR", t("settings.clutchKey.joyconR", { defaultValue: "Joy-Con (R)" })],
					["hidP", t("settings.clutchKey.proController", { defaultValue: "Pro Controller" })],
				];
				const baseButtonOptions = [
					["a", "A"], ["b", "B"], ["x", "X"], ["y", "Y"],
					["up", "↑"], ["down", "↓"], ["left", "←"], ["right", "→"],
					["l", "L"], ["r", "R"], ["zl", "ZL"], ["zr", "ZR"],
					["minus", "−"], ["plus", "+"],
					["home", t("settings.joyconKeyMap.btnHome", { defaultValue: "Home" })],
					["capture", t("settings.joyconKeyMap.btnCapture", { defaultValue: "Capture" })],
					["lstick", t("settings.joyconKeyMap.btnLstick", { defaultValue: "L Stick" })],
					["rstick", t("settings.joyconKeyMap.btnRstick", { defaultValue: "R Stick" })],
					["sl", "SL"], ["sr", "SR"],
				];
				// Desktop stick-direction pseudo buttons (v27): each device's
				// stick can be bound like a button - deflect = key held down,
				// recenter = released. The head-controlled right stick has its
				// own dropdowns under Head → Analog Sticks.
				const stickOptionsFor = (kind) => {
					if (kind === "hidL" || kind === "hidR") {
						return [
							["stickUp", t("settings.joyconKeyMap.stickUp", { defaultValue: "Stick ↑" })],
							["stickDown", t("settings.joyconKeyMap.stickDown", { defaultValue: "Stick ↓" })],
							["stickLeft", t("settings.joyconKeyMap.stickLeft", { defaultValue: "Stick ←" })],
							["stickRight", t("settings.joyconKeyMap.stickRight", { defaultValue: "Stick →" })],
						];
					}
					if (kind === "hidP") {
						return [
							["stickLUp", t("settings.joyconKeyMap.stickLUp", { defaultValue: "L Stick ↑" })],
							["stickLDown", t("settings.joyconKeyMap.stickLDown", { defaultValue: "L Stick ↓" })],
							["stickLLeft", t("settings.joyconKeyMap.stickLLeft", { defaultValue: "L Stick ←" })],
							["stickLRight", t("settings.joyconKeyMap.stickLRight", { defaultValue: "L Stick →" })],
							["stickRUp", t("settings.joyconKeyMap.stickRUp", { defaultValue: "R Stick ↑" })],
							["stickRDown", t("settings.joyconKeyMap.stickRDown", { defaultValue: "R Stick ↓" })],
							["stickRLeft", t("settings.joyconKeyMap.stickRLeft", { defaultValue: "R Stick ←" })],
							["stickRRight", t("settings.joyconKeyMap.stickRRight", { defaultValue: "R Stick →" })],
						];
					}
					return [];
				};
				const buttonOptionsFor = (kind) => [...baseButtonOptions, ...stickOptionsFor(kind)];
				const optionLabel = (options, value) => (options.find(([optionValue]) => optionValue === value) ?? [value, value])[1];
				const highlightDiagram = (kind, name) => {
					ensureJoyconDiagram().highlight(
						kind,
						name,
						`${optionLabel(controllerOptions, kind)} · ${optionLabel(buttonOptionsFor(kind), name)}`,
					);
				};

				const buildSelect = (options, value) => {
					const select = document.createElement("select");
					for (const [optionValue, label] of options) {
						const option = document.createElement("option");
						option.value = optionValue;
						option.textContent = label;
						select.appendChild(option);
					}
					select.value = value;
					return select;
				};
				control.innerHTML = "";
				const commitAndRerender = () => {
					renderKeymapEditor();
					control.dispatchEvent(new Event("change"));
				};
				mappings.forEach((mapping, index) => {
					const row = document.createElement("div");
					row.className = "tracky-mouse-keymap-row";
					const [kind, name] = (mapping.btn || "hidL:a").split(":");
					const controllerSelect = buildSelect(controllerOptions, kind || "hidL");
					const buttonSelect = buildSelect(buttonOptionsFor(kind || "hidL"), name || "a");
					// Keep the button list in sync with the chosen controller:
					// stick-direction entries differ per device (v27).
					const syncButtonOptions = () => {
						const current = buttonSelect.value;
						buttonSelect.replaceChildren();
						for (const [optionValue, labelText] of buttonOptionsFor(controllerSelect.value)) {
							const option = document.createElement("option");
							option.value = optionValue;
							option.textContent = labelText;
							buttonSelect.appendChild(option);
						}
						buttonSelect.value = [...buttonSelect.options].some((option) => option.value === current)
							? current
							: "a";
					};
					controllerSelect.addEventListener("change", () => {
						syncButtonOptions();
						syncDiagram();
					});
					// Point the diagram at this row's button while it's being used.
					const syncDiagram = () => {
						highlightDiagram(controllerSelect.value, buttonSelect.value);
					};
					row.addEventListener("mouseenter", syncDiagram);
					controllerSelect.addEventListener("focus", syncDiagram);
					buttonSelect.addEventListener("focus", syncDiagram);
					const targetButton = document.createElement("button");
					targetButton.type = "button";
					targetButton.className = "tracky-mouse-setting-button tracky-mouse-keymap-target";
					targetButton.textContent = mapping.key
						? clutchKeyDisplayValue(mapping.key, t)
						: t("settings.joyconKeyMap.setTarget", { defaultValue: "Set key…" });
					targetButton.title = t("settings.joyconKeyMap.targetTitle", { defaultValue: "Click, then press keys in order (e.g. hold Ctrl, tap C); the sequence finishes when everything is released. Right-click to type a sequence manually" });
					targetButton.addEventListener("click", () => {
						targetButton.textContent = t("settings.clutchKey.pressSequence", { defaultValue: "Press keys in order… (release all to finish · Esc to cancel)" });
						createKeySequenceCapture({
							keyboardEventToSpec: (event) => event.keyCode
								? "vk:0x" + event.keyCode.toString(16).toUpperCase()
								: null,
							finish: (keySpec) => {
								if (keySpec) {
									mapping.key = keySpec;
								}
								commitAndRerender();
							},
						});
					});
					targetButton.addEventListener("contextmenu", (event) => {
						// Manual sequence entry (added feature, v26): type specs
						// like "ctrl+c" or "vk:0x11+vk:0x43" by hand.
						event.preventDefault();
						event.stopPropagation();
						const input = window.prompt(
							t("settings.joyconKeyMap.editTargetPrompt", { defaultValue: "Key sequence - separate keys with + (e.g. ctrl+c, vk:0x11+vk:0x43, mouse:left):" }),
							mapping.key || "",
						);
						if (input === null) {
							return;
						}
						const value = input.trim();
						mapping.key = value;
						commitAndRerender();
					});
					const deleteButton = document.createElement("button");
					deleteButton.type = "button";
					deleteButton.className = "tracky-mouse-setting-button tracky-mouse-keymap-delete";
					deleteButton.textContent = "×";
					deleteButton.title = t("settings.joyconKeyMap.deleteRow", { defaultValue: "Delete this mapping" });
					// Pick this row's button by physically pressing it on the pad.
					const captureButton = document.createElement("button");
					captureButton.type = "button";
					captureButton.className = "tracky-mouse-setting-button tracky-mouse-keymap-pad-capture";
					captureButton.textContent = t("settings.joyconKeyMap.padCapture", { defaultValue: "Press pad button" });
					captureButton.title = t("settings.joyconKeyMap.padCaptureTitle", { defaultValue: "Click, then press the button on the Joy-Con / Pro Controller (or pick it from the dropdowns)" });
					captureButton.addEventListener("click", () => {
						capturePadButton(captureButton, (btn) => {
							mapping.btn = btn;
							const [capKind, capName] = btn.split(":");
							highlightDiagram(capKind, capName);
							commitAndRerender();
						});
					});
				controllerSelect.addEventListener("change", () => {
					// syncButtonOptions (registered above) already adjusted the
					// button list for the new device; commit with the now-valid
					// button value (stick directions only exist on some devices).
					mapping.btn = controllerSelect.value + ":" + buttonSelect.value;
					syncDiagram();
					commitAndRerender();
				});
					buttonSelect.addEventListener("change", () => {
						mapping.btn = (kind || "hidL") + ":" + buttonSelect.value;
						syncDiagram();
						commitAndRerender();
					});
					deleteButton.addEventListener("click", () => {
						controlValue = mappings.filter((_, i) => i !== index);
						commitAndRerender();
					});
					// Manual sequence entry (added feature, v26): a small edit
					// button opens a prompt where the key sequence can be typed
					// ("ctrl+c", "shift+f5", "vk:0x11+vk:0x43", ...).
					const editButton = document.createElement("button");
					editButton.type = "button";
					editButton.className = "tracky-mouse-setting-button tracky-mouse-keymap-delete";
					editButton.textContent = "…";
					editButton.title = t("settings.joyconKeyMap.editTarget", { defaultValue: "Edit the key sequence manually (keys separated by +, e.g. ctrl+c)" });
					editButton.addEventListener("click", () => {
						const input = window.prompt(
							t("settings.joyconKeyMap.editTargetPrompt", { defaultValue: "Key sequence - separate keys with + (e.g. ctrl+c, vk:0x11+vk:0x43, mouse:left):" }),
							mapping.key || "",
						);
						if (input === null) {
							return;
						}
						mapping.key = input.trim();
						commitAndRerender();
					});
					row.append(captureButton, controllerSelect, buttonSelect, targetButton, editButton, deleteButton);
					control.appendChild(row);
				});
				const addButton = document.createElement("button");
				addButton.type = "button";
				addButton.className = "tracky-mouse-setting-button tracky-mouse-keymap-add";
				addButton.textContent = t("settings.joyconKeyMap.addMapping", { defaultValue: "+ Add mapping" });
				addButton.title = t("settings.joyconKeyMap.addMappingTitle", { defaultValue: "Click, then press a button on the Joy-Con / Pro Controller to add its mapping" });
				addButton.addEventListener("click", () => {
					if (window.electronAPI?.captureClutchGamepad) {
						// Capture first: a new row appears for whichever pad button is pressed.
						capturePadButton(addButton, (btn) => {
							controlValue = [...(Array.isArray(controlValue) ? controlValue : []), { btn, key: "" }];
							const [addKind, addName] = btn.split(":");
							highlightDiagram(addKind, addName);
							commitAndRerender();
						});
						return;
					}
					controlValue = [...(Array.isArray(controlValue) ? controlValue : []), { btn: "hidR:a", key: "" }];
					commitAndRerender();
				});
				control.appendChild(addButton);
			};
			functionsToUpdateDisabledStates.push(() => {
				const dis = setting.disabled?.() === true;
				control.style.opacity = dis ? "0.5" : "";
				control.style.pointerEvents = dis ? "none" : "";
			});
			renderKeymapEditor();
			// Reflect the initial disabled state.
			for (const func of functionsToUpdateDisabledStates.slice(-1)) {
				func();
			}
			// Stop any in-progress pad-button capture when the settings UI goes away.
			disposeSignal.addEventListener("abort", () => {
				if (padCaptureStop) {
					window.electronAPI?.cancelClutchGamepadCapture?.();
					padCaptureStop();
					padCaptureStop = null;
				}
			});
		}

		return rowEl;
	}

	buildSettingsUI(uiContainer.querySelector(".tracky-mouse-controls"), settingsCategories);

	const runAtLoginCheckbox = uiContainer.querySelector(".tracky-mouse-run-at-login");
	const swapMouseButtonsCheckbox = uiContainer.querySelector(".tracky-mouse-swap-mouse-buttons");
	const swapMouseButtonsLabel = uiContainer.querySelector("label[for='tracky-mouse-swap-mouse-buttons']");
	const cameraSelect = uiContainer.querySelector(".tracky-mouse-camera-select");

	if (window.electronAPI) {
		// Disable the "run at login" option if the app isn't packaged,
		// as it's not set up to work in development mode.
		window.electronAPI.getIsPackaged().then((isPackaged) => {
			runAtLoginCheckbox.disabled = !isPackaged;
		});
	}

	// Handle right click on "swap mouse buttons", so it doesn't leave users stranded right-clicking.
	// Note that if you click outside the application window, hiding it behind another window, or minimize it,
	// you can still be left in a tricky situation.
	// A more general safety net would be a "revert changes?" timer (https://github.com/1j01/tracky-mouse/issues/43)
	// But this is good to have in any case, since you don't want to have to wait for a timeout if you don't have to.
	for (const el of [swapMouseButtonsLabel, swapMouseButtonsCheckbox]) {
		el.addEventListener("contextmenu", (e) => {
			e.preventDefault();
			swapMouseButtonsCheckbox.checked = !swapMouseButtonsCheckbox.checked;
			swapMouseButtonsCheckbox.dispatchEvent(new Event("change"));
		});
	}

	let populateCameraList = () => { return Promise.resolve(); };
	if (navigator.mediaDevices && navigator.mediaDevices.enumerateDevices) {
		populateCameraList = () => {
			let matchedCameraIdDeferred = createDeferred();
			navigator.mediaDevices.enumerateDevices().then((devices) => {
				const videoDevices = devices.filter(device => device.kind === 'videoinput');

				let knownCameras = {};
				try {
					knownCameras = JSON.parse(localStorage.getItem("tracky-mouse-known-cameras")) || {};
				} catch (error) {
					console.error("Failed to parse known cameras from localStorage", error);
				}
				let knownCamerasChanged = false;
				for (const device of videoDevices) {
					if (device.deviceId && device.label) {
						if (!knownCameras[device.deviceId] || knownCameras[device.deviceId].name !== device.label) {
							knownCameras[device.deviceId] = { name: device.label };
							knownCamerasChanged = true;
						}
					}
				}
				if (knownCamerasChanged) {
					try {
						localStorage.setItem("tracky-mouse-known-cameras", JSON.stringify(knownCameras));
					} catch (error) {
						console.error("Failed to store known cameras in localStorage", error);
					}
				}

				cameraSelect.innerHTML = "";

				const defaultOption = document.createElement("option");
				defaultOption.value = "";
				defaultOption.text = t("settings.cameraSource.defaultCamera", { defaultValue: "Default" });
				cameraSelect.appendChild(defaultOption);

				let matchingDeviceId = "";
				for (const device of videoDevices) {
					const option = document.createElement('option');
					option.value = device.deviceId;
					option.text = device.label || t("settings.cameraSource.numberedCamera", { defaultValue: "Camera %0" }).replace("%0", cameraSelect.length);
					cameraSelect.appendChild(option);
					if (device.deviceId === s.cameraDeviceId) {
						matchingDeviceId = device.deviceId;
					} else if (device.label === knownCameras[s.cameraDeviceId]?.name) {
						matchingDeviceId ||= device.deviceId;
					}
				}

				// Defaulting to "Default" would imply a preference isn't stored...
				// but would it be more friendly anyways?
				// cameraSelect.value = found ? s.cameraDeviceId : "";

				// Show a placeholder for the selected camera
				if (s.cameraDeviceId && !matchingDeviceId) {
					const option = document.createElement("option");
					option.value = s.cameraDeviceId;
					const knownInfo = knownCameras[s.cameraDeviceId];
					option.text = knownInfo ? `${knownInfo.name} (${t("settings.cameraSource.unavailableCameraAdjective", { defaultValue: "Unavailable" })})` : t("settings.cameraSource.unavailableCamera", { defaultValue: "Unavailable camera" });
					cameraSelect.appendChild(option);
					cameraSelect.value = s.cameraDeviceId;
				} else {
					cameraSelect.value = matchingDeviceId;
				}
				matchedCameraIdDeferred.resolve(matchingDeviceId);
			});
			return matchedCameraIdDeferred.promise;
		};
		populateCameraList();
		navigator.mediaDevices.addEventListener('devicechange', populateCameraList);
	}


	return {
		populateCameraList,
		updateDisabledStates: () => {
			for (const func of functionsToUpdateDisabledStates) {
				func();
			}
		},
		// `dispose` would be a more natural name, but I'm just making it
		// easy to use destructuring for now
		disposeSettingsUI: () => {
			disposeController.abort();
		},
	};
}
